function g(t){return t.getFullYear()+"-"+String(t.getMonth()+1).padStart(2,"0")+"-"+String(t.getDate()).padStart(2,"0")}function o(t){return String(t).padStart(2,"0")}function c(t){let n=/^(\d{4})-(\d{2})$/.exec(t);if(!n)throw new Error("Month must use YYYY-MM format.");let r=Number(n[1]),e=Number(n[2])-1,a=new Date(r,e+1,0).getDate();return {from:`${r}-${o(e+1)}-01`,to:`${r}-${o(e+1)}-${o(a)}`}}function m(t){let{from:n,to:r}=c(t),[e,a]=n.split("-").map(Number),s=Number(r.slice(-2)),h=new Date(e,a-1,1).getDay(),u=Array.from({length:h},()=>({date:null,day:null}));for(let l=1;l<=s;l+=1)u.push({date:`${e}-${o(a)}-${o(l)}`,day:l});for(;u.length%7;)u.push({date:null,day:null});return u}function d(t,n){let{from:r}=c(t),e=new Date(`${r}T00:00:00`);return e.setMonth(e.getMonth()+n),`${e.getFullYear()}-${o(e.getMonth()+1)}`}function i(t=new Date){return `${t.getFullYear()}-${o(t.getMonth()+1)}`}export{c,d,g,i,m};